struct DebugInfo {
  std::vector<int> lineForPc;      // pc -> source row in the quest sheet
  std::string scriptName;
};

void VM::fail(const char* msg) {
  int line = debug_->lineForPc[pc_];
  log("%s:%d: %s (stack size %d)",
      debug_->scriptName.c_str(), line, msg, stackSize_);
}

bool VM::interpret(const uint8_t* code, int size) {
  int executed = 0;
  for (int i = 0; i < size; i++) {
    if (++executed > MAX_INSTRUCTIONS) return fail("too many steps");
    switch (code[i]) {
      case INST_LITERAL:
        if (i + 1 >= size) return fail("truncated literal");
        if (!push(code[++i])) return fail("stack overflow");
        break;
      case INST_ADD: {
        int a, b;
        if (!pop(b) || !pop(a)) return fail("stack underflow");
        push(a + b);
        break;
      }
      // ...
      default:
        return fail("unknown opcode");
    }
  }
  return true;
}

