// Editor side: node tree -> bytecode (Interpreter-pattern-shaped).
void IfNode::emit(Emitter& out) {
  cond_->emit(out);
  int patch = out.emitJumpIfFalse();
  body_->emit(out);
  out.patchJump(patch);
}
